func (l *McpShellLexer) Sempred(localctx antlr.RuleContext, ruleIndex, predIndex int) bool {
	switch ruleIndex {
	case 57:
		return l.REGEX_Sempred(localctx, predIndex)

	default:
		panic("No registered predicate for: " + fmt.Sprint(ruleIndex))
	}
}

func (p *McpShellLexer) REGEX_Sempred(localctx antlr.RuleContext, predIndex int) bool {
	switch predIndex {
	case 0:
		return !p.prevTokenCouldEndExpr()

	default:
		panic("No predicate with index: " + fmt.Sprint(predIndex))
	}
}
